option.value:
/* Reset & Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: sans-serif;
}

body {
    background-color: #fff;
    color: #111827;
}

/* Container */
.container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 40px;
}

/* HEADER */
.header {
    background-color: #ffffff;
    border-bottom: 1px solid #e5e7eb;
}

.header-container {
    height: 48px;
}

.nav-left,
.nav-right {
    display: flex;
    align-items: center;
    gap: 20px;
}

.nav-left h5,
.nav-right h5,
.nav-right i {
    color: #6b7280;
    font-size: 14px;
    font-weight: 300;
    cursor: pointer;
    transition: color 0.2s;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.nav-item {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
}

/* Hover effects - item içindeki hem icon hem de h5 grey olur */
.nav-item:hover h5,
.nav-item:hover i {
    color: #9ca3af;
}

/* Sol taraftaki elementlerin hover efekti */
.nav-left h5:hover {
    color: #9ca3af;
}

/* MAIN BAR - Logo ve Search Bar Yan Yana */
.main-bar {
    background-color: #fff;
    border-bottom: 1px solid #e5e7eb;
    padding: 20px 0;
}

.main-bar-container {
    display: flex;
    align-items: center;
    gap: 32px;
}

.cyberstore-left {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    flex-shrink: 0;
}

.cyberstore-logo {
    font-size: 24px;
    letter-spacing: 2px;
    font-weight: 700;
}

.cyberstore-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background-color: #3b82f6;
    margin-bottom: 6px;
}


/* Navigation Menu */
.navigation-menu {
    display: flex;
}

.main-nav {
    display: flex;
    align-items: center;
    gap: 20px;
}

.main-nav a {
    color: #1f2937;
    text-decoration: none;
    font-size: 14px;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    transition: color 0.2s;
}

.main-nav a:hover {
    color: #7c3aed;
}

/* Compact Search Field */
.search-field-compact {
    display: flex;
    flex: 0 0 280px;
}

.search-field-compact input {
    flex: 1;
    height: 42px;
    border-radius: 999px 0 0 999px;
    border: 1px solid #d1d5db;
    background-color: #fff;
    padding: 0 16px;
    font-size: 14px;
}

.search-field-compact input:focus {
    outline: none;
    border-color: #7c3aed;
}

.search-button-compact {
    width: 42px;
    height: 42px;
    border-radius: 0 999px 999px 0;
    border: none;
    background-color: #7c3aed;
    color: #fff;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background-color 0.2s;
}

.search-button-compact:hover {
    background-color: #6d28d9;
}

/* Header Icons */
.header-icons {
    display: flex;
    align-items: center;
    gap: 16px;
}

.icon-button {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    border: 1px solid #e5e7eb;
    background-color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s;
}

.icon-button i {
    font-size: 18px;
    color: #1f2937;
    transition: color 0.2s;
}

.icon-button:hover {
    border-color: #7c3aed;
}

.icon-button:hover i {
    color: #7c3aed;
}

.cart-button {
    display: flex;
    align-items: center;
    cursor: pointer;
    border: none;
    background: none;
}

.cart-icon-wrapper {
    width: 42px;
    height: 42px;
    position: relative;
    border-radius: 50%;
    border: 1px solid #e5e7eb;
    background-color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
}

.cart-icon-wrapper i {
    font-size: 18px;
    color: #1f2937;
    transition: color 0.2s;
}

.cart-button:hover .cart-icon-wrapper {
    border-color: #7c3aed;
}

.cart-button:hover .cart-icon-wrapper i {
    color: #7c3aed;
}

.cart-badge {
    position: absolute;
    top: -3px;
    right: -3px;
    min-width: 16px;
    height: 16px;
    background-color: #7c3aed;
    color: #fff;
    border-radius: 999px;
    font-size: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
}

