/* CONTACT BANNER */
.contact-banner {
    width: 100%;
    height: 293px;
    background-color: #7c3aed;
    display: flex;
    align-items: center;
    justify-content: center;
}

.contact-banner-content {
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
}

.contact-banner h1 {
    color: #fff;
    font-size: 48px;
    font-weight: 700;
    letter-spacing: 2px;
    margin: 0;
}

.contact-banner .breadcrumb {
    color: #e9d5ff;
    font-size: 16px;
    font-weight: 400;
    margin: 0;
}
